// Calculate pressure force
for (size_t i = start; i < end; i++) {
    Particle& p = particles[i];
    glm::vec3 pressureForce(0.0f);

    // Get cell coordinates for current particle
    glm::ivec3 cell = getCell(&p, h);

    // Check neighboring cells (27 cells in 3D space)
    for (int x = -1; x <= 1; x++) {
        for (int y = -1; y <= 1; y++) {
            for (int z = -1; z <= 1; z++) {
                glm::ivec3 neighborCell = cell + glm::ivec3(x, y, z);
                uint32_t neighborHash = getHash(neighborCell);

                // Get first neighbor in this cell
                uint32_t neighborIndex = particleTable[neighborHash];
                while (neighborIndex != NO_PARTICLE) {
                    Particle& neighbor = particles[neighborIndex];

                    // Calculate distance between particles
                    glm::vec3 r = neighbor.position - p.position;
                    float rSquared = glm::dot(r, r);
                    float r = std::sqrt(rSquared);

                    // Skip if outside kernel support
                    if (r > h) {
                        neighborIndex = neighbor.nextInCell;
                        continue;
                    }

                    // Calculate kernel and gradient terms
                    float kernel = sphGPU::poly6Kernel(rSquared, h2);
                    float gradKernel = sphGPU::spikyGradKernel(rSquared, h2);

                    // Pressure force contribution
                    float pressureDiff = (p.pressure + neighbor.pressure) / 2.0f;
                    glm::vec3 force = pressureDiff * gradKernel * r;
                    pressureForce += force;

                    neighborIndex = neighbor.nextInCell;
                }
            }
        }
    }

    // Viscosity force
    glm::vec3 viscosityForce(0.0f);
    for (int x = -1; x <= 1; x++) {
        for (int y = -1; y <= 1; y++) {
            for (int z = -1; z <= 1; z++) {
                glm::ivec3 neighborCell = cell + glm::ivec3(x, y, z);
                uint32_t neighborHash = getHash(neighborCell);

                uint32_t neighborIndex = particleTable[neighborHash];
                while (neighborIndex != NO_PARTICLE) {
                    Particle& neighbor = particles[neighborIndex];

                    glm::vec3 r = neighbor.position - p.position;
                    float rSquared = glm::dot(r, r);
                    float r = std::sqrt(rSquared);

                    if (r > h) {
                        neighborIndex = neighbor.nextInCell;
                        continue;
                    }

                    // Calculate viscosity force
                    float lapKernel = sphGPU::spikyLapKernel(rSquared, h2);
                    glm::vec3 relativeVel = neighbor.velocity - p.velocity;
                    glm::vec3 force = viscosity * lapKernel * relativeVel;
                    viscosityForce += force;

                    neighborIndex = neighbor.nextInCell;
                }
            }
        }
    }

    // Apply forces
    p.force += pressureForce + viscosityForce;
}

